    protected const PARAMETERS = ['organization' => ['type' => 'string', 'required' => true, 'description' => 'The name of the Azure DevOps organization.'], 'project' => ['type' => 'string', 'required' => true, 'description' => 'Project ID or project name'], 'repository' => ['type' => 'string', 'required' => true, 'description' => 'The name or ID of the repository'], 'top' => ['type' => 'number', 'required' => false, 'description' => 'The maximum number of alerts to return'], 'order_by' => ['type' => 'string', 'required' => false, 'description' => 'Must be "id" "firstSeen" "lastSeen" "fixedOn" or "severity" Defaults to "id"'], 'criteria_alert_ids' => ['type' => 'array', 'required' => false, 'description' => 'If provided, only return alerts with the ids specified. <br />Otherwise, return any alert.'], 'criteria_alert_type' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts of this type. Otherwise, return alerts of all types.'], 'criteria_confidence_levels' => ['type' => 'array', 'required' => false, 'description' => 'If provided, only return alerts at these confidence levels. <br />Both High and Other need to be specified to fetch alerts of all confidence levels. <br />Otherwise, return alerts with high confidence level. <br />Only applicable for secret alerts.'], 'criteria_dependency_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only alerts for this dependency are returned. <br />Otherwise, return alerts for all dependencies. <br />In a sarif submission, a dependency (or a component) is specified in result.RelatedLocations[].logicalLocation. <br />Not applicable for secret alerts.'], 'criteria_from_date' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts last seen after this date. <br />Otherwise return all alerts.'], 'criteria_has_linked_work_items' => ['type' => 'boolean', 'required' => false, 'description' => 'If provided, filters alerts based on whether they have linked work items. <br />Set to "true" to return only alerts with linked work items. <br />Set to "false" to return only alerts without linked work items. <br />If not provided, returns all alerts regardless of linked work items. <br />Not applicable for secret and dependency scanning alerts.'], 'criteria_is_triaged' => ['type' => 'boolean', 'required' => false, 'description' => 'If provided with isTriaged, only return alerts that have been triaged. <br />Otherwise, return alerts regardless of triage status.'], 'criteria_keywords' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts whose titles match this pattern.'], 'criteria_license_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only alerts created for dependency with this license are returned. <br />Otherwise, return alerts for all licenses. <br />In a sarif submission, license for a dependency (or a component) is specified in result.RelatedLocations[].logicalLocation.properties.license. <br />Not applicable for secret alerts.'], 'criteria_modified_since' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts that were modified since this date. <br />Otherwise return all alerts.'], 'criteria_only_default_branch' => ['type' => 'boolean', 'required' => false, 'description' => 'If true or not set, only return alerts found on the default branch of the repository. <br />If there have been no runs completed on the default branch, the last run is used instead regardless of the branch used for that run. If false, return alerts from all branches. <br />This option is ignored if ref is provided. <br />Not applicable for secret alerts.'], 'criteria_phase_id' => ['type' => 'string', 'required' => false, 'description' => 'If provided with pipelineName, only return alerts detected in this pipeline phase <br />Otherwise, return alerts detected in all phases. <br />Not applicable for secret alerts.'], 'criteria_phase_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided with pipelineName, only return alerts detected in this pipeline phase <br />Otherwise, return alerts detected in all phases. <br />Not applicable for secret alerts.'], 'criteria_pipeline_id' => ['type' => 'number', 'required' => false, 'description' => 'If provided with pipelineId, only return alerts detected in this pipeline <br />Otherwise, return alerts detected in all pipelines.'], 'criteria_pipeline_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts detected in this pipeline. <br />Otherwise, return alerts detected in all pipelines. <br />Not applicable for secret alerts.'], 'criteria_ref' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only include alerts for this ref. <br />If not provided and OnlyDefaultBranch is true, only include alerts found on the default branch or last run branch if there is no analysis configuration for the default branch. <br />Otherwise, include alerts from all branches. <br />Not applicable for secret alerts.'], 'criteria_rule_id' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts for this rule. <br />Otherwise, return alerts of all rules.'], 'criteria_rule_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts for this rule. <br />Otherwise, return alerts for all rules.'], 'criteria_severities' => ['type' => 'array', 'required' => false, 'description' => 'If provided, only return alerts at these severities. <br />Otherwise, return alerts at any severity.'], 'criteria_states' => ['type' => 'array', 'required' => false, 'description' => 'If provided, only return alerts in these states. <br />Otherwise, return alerts in any state.'], 'criteria_to_date' => ['type' => 'string', 'required' => false, 'description' => 'If provided, only return alerts last seen before this date. <br />Otherwise return all alerts.'], 'criteria_tool_name' => ['type' => 'string', 'required' => false, 'description' => 'If provided with toolName, only return alerts detected by this tool. <br />Otherwise, return alerts detected by all tools.'], 'criteria_validity' => ['type' => 'array', 'required' => false, 'description' => 'If provided, only return alerts with the validity specified here. If the validity status is Unknown, fetch alerts of all validity results. <br />Only applicable for secret alerts. <br />Filtering by validity status may cause less alerts to be returned than requested with TOP parameter. <br />Due to this behavior, the ContinuationToken(<![CDATA[<header name>]]>) in the response header should be relied on to decide if another batch needs to be fetched.'], 'expand' => ['type' => 'string', 'required' => false, 'description' => 'query parameter `expand`.'], 'continuation_token' => ['type' => 'string', 'required' => false, 'description' => 'If there are more alerts than can be returned, a continuation token is placed in the "x-ms-continuationtoken" header. Use that token here to get the next page of alerts'], 'api_version' => ['type' => 'string', 'required' => false, 'description' => 'Azure DevOps API version. Defaults to `7.2-preview.1`.']];
    protected const METHOD = 'GET';
